-- MA 1.0 → 1.1: Owner decisions D2, D12, D13, D19 (docs/questionbank/decisions.md)
-- Generated by `npm run qb:patch`. Run once in the Supabase SQL Editor. One transaction: if any step
-- or the validation fails, nothing is saved. Publishes the new version (testing databases).
DO $qbpatch$
DECLARE
  v uuid;
  n integer;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.qb_versions WHERE test_code = 'MA' AND version_label = '1.0' AND status = 'live') THEN
    RAISE EXCEPTION 'MA 1.0 must be the live version.';
  END IF;
  v := public.qb_start_new_version('MA', '1.1');
  UPDATE public.qb_versions SET change_note = 'Owner decisions D2, D12, D13, D19 (docs/questionbank/decisions.md)' WHERE id = v;

  -- 1. D2: set_option
  UPDATE public.qb_options SET exclusive = true WHERE version_id = v AND qid = 'MR1' AND option_code = 'none_of_these';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'Patch operation 1 (set_option, D2): expected 1 option, got %', n; END IF;

  -- 2. D19: set_flag
  UPDATE public.qb_flags SET effects = effects || $qbj${"notify":["coordinator","counsellor"]}$qbj$::jsonb WHERE version_id = v AND key = 'CRISIS';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'Patch operation 2 (set_flag, D19): expected 1 flag, got %', n; END IF;

  -- 3. D19: set_flag
  UPDATE public.qb_flags SET effects = effects || $qbj${"notify":["coordinator","counsellor"]}$qbj$::jsonb WHERE version_id = v AND key = 'SAFETY';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'Patch operation 3 (set_flag, D19): expected 1 flag, got %', n; END IF;

  -- 4. D12: set_scoring
  UPDATE public.qb_scoring SET gate = gate || $qbj${"min_choices":1}$qbj$::jsonb WHERE version_id = v;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'Patch operation 4 (set_scoring, D12): expected 1 qb_scoring row, got %', n; END IF;

  -- 5. D13: set_report_rules
  UPDATE public.qb_report_rules SET interpretation = interpretation || $qbj${"fallback":"core"}$qbj$::jsonb WHERE version_id = v;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'Patch operation 5 (set_report_rules, D13): expected 1 qb_report_rules row, got %', n; END IF;

  -- 6. D13: add_test_case
  INSERT INTO public.qb_test_cases (version_id, name, source, context, answers, expected, verified, notes) VALUES (v, 'LOW_MODULE_FALLBACK', 'manual', $qbj${"sex":"female","age":30,"path":null}$qbj$::jsonb, $qbj${"MI1":"25_34","MI2":"female","MI3":"working_job","MI4":"india","MI5":"english","MG1":["W"],"MC7":"sometimes","MC1":"rarely","MC2":"rarely","MC3":"sometimes","MC4":"sometimes","MC5":"sometimes","MC6":"rarely","MC8":"sometimes","MC9":"rarely","MC10":"sometimes","W1":"rarely","W2":"rarely","W3":"rarely","W4":"rarely","W5":"never","W6":"never","W7":"never","W8":"often","MD1":"3_12_months","MD2":"a_little","MD3":"nothing_yet","MD4":"yes","MR1":["none_of_these"],"MR2":"no","MR4":"never","MR5":"no","MR6":"no"}$qbj$::jsonb, $qbj${"bands":{"MCORE":"Moderate","W":"Low"},"primary":"W","points":{"SEVERITY":0,"DURATION":1,"IMPACT":1,"MULTI_AREA":0,"PRIOR_ATTEMPTS":0,"ISOLATION":0,"TOTAL":2},"tier":4,"format":"individual","flags":[],"layout":"standard","interpretation_keys":["INTERP_MCORE_MODERATE"]}$qbj$::jsonb, false, 'Female 30, working, chose W, W band Low, MCORE Moderate (D13). Intended module %: MCORE 17/27 = 63% (Moderate) · W 4/24 = 17% (Low). Points SEVERITY 0 + DURATION 1 + IMPACT 1 + MULTI_AREA 0 + PRIOR_ATTEMPTS 0 + ISOLATION 0 = 2. There is no INTERP_W_LOW, so the primary line falls back to INTERP_MCORE_MODERATE; printed once.');

  -- 7. D19: add_test_case
  INSERT INTO public.qb_test_cases (version_id, name, source, context, answers, expected, verified, notes) VALUES (v, 'CRISIS_NOTIFY', 'manual', $qbj${"sex":"male","age":27,"path":null}$qbj$::jsonb, $qbj${"MI1":"25_34","MI2":"male","MI3":"working_job","MI4":"india","MI5":"english","MG1":["H"],"MC7":"sometimes","MC1":"rarely","MC2":"sometimes","MC3":"rarely","MC4":"rarely","MC5":"rarely","MC6":"sometimes","MC8":"rarely","MC9":"sometimes","MC10":"sometimes","H1":"sometimes","H2":"sometimes","H3":"sometimes","H4":"sometimes","H5":"sometimes","H6":"sometimes","H7":"sometimes","H8":"sometimes","MD1":"3_12_months","MD2":"quite_a_lot","MD3":"nothing_yet","MD4":"somewhat","MR1":["none_of_these"],"MR2":"no","MR4":"never","MR5":"yes","MR6":"no","MR3":"no"}$qbj$::jsonb, $qbj${"bands":{"MCORE":"Mild","H":"Moderate"},"primary":"H","points":{"SEVERITY":2,"DURATION":1,"IMPACT":2,"MULTI_AREA":0,"PRIOR_ATTEMPTS":0,"ISOLATION":0,"TOTAL":5},"tier":6,"format":"individual","flags":["CRISIS"],"layout":"crisis","notify":["coordinator","counsellor"]}$qbj$::jsonb, false, 'Male 27, working, chose H, MR5 = Yes (D19). Intended module %: MCORE 10/27 = 37% (Mild) · H 16/24 = 67% (Moderate). Points SEVERITY 2 + DURATION 1 + IMPACT 2 + MULTI_AREA 0 + PRIOR_ATTEMPTS 0 + ISOLATION 0 = 5. Crisis layout: the plan is hidden in the report; the tier (6) is still calculated and stored.');

  -- Zero validation errors, or nothing is saved.
  PERFORM public.qb_raise_if_invalid(v);
  PERFORM public.qb_submit_for_review(v);
  PERFORM public.qb_publish(v, 'MA 1.1: owner decisions D2, D12, D13, D19 (testing)');
  RAISE NOTICE 'MA 1.1 is live (%).', v;
END
$qbpatch$;
